package org.brightstats.data;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import com.google.gson.*;
import org.brightstats.stats.*;
/** Export a separate editable stage-two model, retaining explicit fixed-score provenance. */
public final class HigherOrderProjects {
    private HigherOrderProjects(){}
    public static JsonObject create(JsonObject source,HigherOrderPls.Fit fit){Gson gson=new Gson();double[][] data=gson.fromJson(source.get("observations"),double[][].class);if(data.length!=fit.observations()||Matrices.width(data,3)!=fit.originalColumns())throw new IllegalArgumentException("The source dataset differs from the higher-order result.");double[][] augmented=HigherOrderPls.augment(data,fit.firstStage().scores());List<String> names=new ArrayList<>();if(source.has("columnNames")){for(var name:source.getAsJsonArray("columnNames")){if(!name.isJsonPrimitive()||!name.getAsJsonPrimitive().isString())throw new IllegalArgumentException("Source column names must be strings.");names.add(name.getAsString());}}else for(int j=0;j<fit.originalColumns();j++)names.add("X"+(j+1));if(names.size()!=fit.originalColumns()||new HashSet<>(names).size()!=names.size()||names.stream().anyMatch(String::isBlank))throw new IllegalArgumentException("Source header count or uniqueness differ.");for(var block:fit.firstStageBlocks()){String name="Stage-one score: "+block.name();while(names.contains(name))name+=" (score)";names.add(name);}JsonObject result=new JsonObject();result.addProperty("formatVersion",1);result.add("observations",gson.toJsonTree(augmented));result.add("columnNames",gson.toJsonTree(names));result.add("blocks",gson.toJsonTree(fit.secondStageBlocks()));result.add("edges",gson.toJsonTree(fit.specification().edges()));result.add("options",gson.toJsonTree(fit.specification().options()));JsonObject metadata=new JsonObject();metadata.addProperty("format","bright-stats-derived-data");metadata.addProperty("formatVersion",1);metadata.addProperty("kind","higher-order-stage-two");JsonObject parent=new JsonObject();parent.add("source",source);parent.add("specification",gson.toJsonTree(fit.specification()));parent.add("firstStageOptions",gson.toJsonTree(fit.firstStageOptions()));try{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(var writer=new java.io.OutputStreamWriter(new java.security.DigestOutputStream(java.io.OutputStream.nullOutputStream(),digest),StandardCharsets.UTF_8)){gson.toJson(parent,writer);}metadata.addProperty("sourceSha256",HexFormat.of().formatHex(digest.digest()));}catch(NoSuchAlgorithmException|java.io.IOException impossible){throw new IllegalStateException(impossible);}metadata.addProperty("scoreColumnStart",fit.originalColumns());metadata.addProperty("scoreColumns",fit.firstStageBlocks().size());result.add("derivation",ProjectDerivation.validate(metadata,names.size()));return result;}
}
